cd /tmp/vally-eval-trial-mZoZJL && cat > src/CheckoutPricing.Application/CheckoutPricingService.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Standard,
    Gold,
}

public sealed class CheckoutPricingService
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysThe95()
    {
        var total = new CheckoutPricingService().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

